let roleStage='role',registration=false,eventExpanded=false,merchantExpanded='',connectMode='phone',depositSource='',depositDraft=0,paypalStage='method',selectedCatalog='',editingBooks=false,editingLists=false,inviteContact='',inviteDraft='',sourceReceiptFilter=false;
const contactPhones={'Jim Carlson':'(555) 379-9924','Leo Daniels':'(555) 123-4567','Emma Brewer':'(555) 567-9900','Ron Owens':'(555) 345-0099','Peter Webb':'(555) 234-6540','Jeffrey Hunt':'(555) 379-9223','Phyllis Weaver':'(555) 222-3458'};
const vampireCatalog={'Daren Magnus':'Vampires of the Mires, and other gost...','Lucy Sadle':'Vampires of the Mires, a Love Story','Jenifer Taako':'Vamipres and grassland conservation','Karen Lee':'Mosqitoes- Vampires of the Marsh','Von Craen':'Vimpires of the Grimpen Mires'};
Object.assign(bookNames,vampireCatalog);
const fidelityTitles={'role':'','student-id':'','paypal':'PayPal','deposit-source':'Add Funds Now','purchase':'Complete Your Purchase','first-year':'First Year',donations:'donations',groups:'groups',careers:'careers','invite-compose':'New Message','camera':'','photo-preview':'','photo-library':'Photos','pay-overlay':'','reward-overlay':'','pin-current':'Enter PIN','book-search':'My Booklist','ebook':'','tutorial':'New Message'};
const fidelityPages={'role':()=>auth(),'student-id':()=>auth(),paypal:()=>paypalScreen(),'deposit-source':()=>depositSourceScreen(),'first-year':()=>firstYearScreen(),donations:()=>sourceDestination('donations'),groups:()=>sourceDestination('groups'),careers:()=>sourceDestination('careers'),'invite-compose':()=>inviteComposer(),camera:()=>cameraScreen(),'photo-preview':()=>photoPreview(),'photo-library':()=>photoLibrary(),'pay-overlay':()=>home(),'reward-overlay':()=>home(),'pin-current':()=>pinCurrent(),'book-search':()=>bookSearchDetail(),ebook:()=>externalBooks(),tutorial:()=>contactList()};
const sourceSkinFile=(state)=>({role:{QC:'onboarding-07',BU:'changeschool-02',GC:'changeschool-09'},id:{QC:'onboarding-09',BU:'changeschool-04',GC:'changeschool-11'},login:{QC:'onboarding-10',BU:'changeschool-05',GC:'changeschool-12'}}[state][schoolChoice]||'onboarding-07');
const helpBar=()=>`<div class="help-bar">${[['help-bar-phone','CALL SUPPORT'],['help-bar-mail','SEND EMAIL'],['help-bar-web','GO TO WEBSITE']].map(([i,t])=>B(`${I(i)}<span>${t}</span>`,'help','','')).join('')}</div>`;
function auth(){
 if(route==='onboarding'&&formStage===0)return `<form id="start-form" class="source-auth front-screen" style="background-image:url('screens/onboarding-01.jpg')"><input class="front-phone" type="tel" name="phone" aria-label="ENTER YOUR PHONE NUMBER" placeholder="ENTER YOUR PHONE NUMBER" required><button class="source-continue" type="submit">CLICK TO START</button></form>`;
 if(route==='school'&&registration)return `<section class="source-auth source-school-choose" style="background-image:url('screens/onboarding-06.jpg')"><div class="source-picker">${['H','BU','QC','GC','SH'].map(t=>B(t,'school-choice',schoolChoice===t?'selected':'',t)).join('')}</div>${B('CONTINUE','school-continue','source-continue')}</section>`;
 if(route==='school')return `<section class="auth"><div class="college-header">${collegeLogo(schoolChoice)}</div><img class="wordmark" src="assets/wordmark.png" alt="looped in"><div class="auth-spacer"></div><p class="school-selection-title">${registration?'SELECT YOUR SCHOOL':'CHANGE YOUR SCHOOL'}</p><div class="school-choices">${['H','BU','QC','GC','SH'].map(t=>B(['BU','QC','GC'].includes(t)?collegeLogo(t):`<span class="original-school original-school-${t}"></span>`,'school-choice',schoolChoice===t?'selected':'',t)).join('')}</div><div class="auth-spacer"></div>${B('CONTINUE','school-continue','primary wide')}</section>`;
 if(route==='role'||route==='student-id'||route==='onboarding'&&formStage>=4){const isID=route==='student-id';return `<form id="${isID?'student-id-form':'choose-role-form'}" class="source-auth" style="background-image:url('screens/${sourceSkinFile(isID?'id':'role')}.jpg')">${isID?`<input class="source-student-id" type="text" name="student" aria-label="ENTER YOUR STUDENT ID" placeholder="ENTER YOUR STUDENT ID" required>`:`<select class="source-role" name="role" aria-label="I AM ..." required><option value="">I AM ...</option>${['Student','First Year Student','Alumni','Parent/Gardian'].map(t=>`<option ${authData.role===t?'selected':''}>${t}</option>`).join('')}</select>`}<button class="source-continue" type="submit">${isID?'FINISH':'CONTINUE'}</button></form>`;}
 if(route==='login')return `<form id="login-form" class="source-auth" style="background-image:url('screens/${sourceSkinFile('login')}.jpg')"><input class="source-login-user" type="tel" name="student" aria-label="Phone number" value="${esc(authData.phone||'555 332 1621')}" required><input class="source-login-password" type="password" name="password" aria-label="Password" autocomplete="off" required><label class="source-remember"><span>REMEMBER ME</span><input class="switch" type="checkbox" name="remember"></label>${B('FORGOT PASSWORD','forgot','source-forgot')}<button type="submit" class="source-continue">LOGIN</button></form>`;
 const fields=formStage===1?field('First name','first','text',authData.first||'','required')+field('Enter Email','email','email',authData.email||'','required')+field('Create Password','password','password','','required minlength="4"')+field('Confirm Password','confirm','password','','required'):formStage===2?`<label class="field">Select a security question:<input name="question" required></label>`+field('Your answer:','answer','text','','required')+field('Confirm answer:','confirmAnswer','text','','required'):field('Create PIN to secure your account:','pin','password','','required pattern="[0-9]{4}" maxlength="4" inputmode="numeric"')+field('Confirm PIN:','confirmPin','password','','required pattern="[0-9]{4}" maxlength="4" inputmode="numeric"');
 return helpBar()+`<form id="onboarding-form" class="pad stack">${fields}${formStage===3?'<p class="source-small-copy">You will need your PIN to securely load money into your account, send money to a friend and to pay for goods.</p>':''}<div class="progress">${[1,2,3,4].map(n=>`<span class="${n<=formStage?'active':''}"></span>`).join('')}</div><span class="muted" style="text-align:center">step ${formStage} of 4</span><button class="green wide" type="submit">CONTINUE</button></form>`;
}
function contactList(){return `<div class="toolbar"><span class="muted">To:</span>${search('Search contacts',contactQuery,'contact-search')}</div><div class="list" id="contact-results">${contacts.filter(c=>c.toLowerCase().includes(contactQuery.toLowerCase())).map(c=>`<button class="list-row" data-action="choose-contact" data-value="${c}"><span class="contact-initial">${c.split(' ').map(n=>n[0]).join('')}</span><span class="grow">${c}<small>${contactPhones[c]}</small></span></button>`).join('')}</div>`;}
function finances(){const points=(SCHOOL_SKINS[S.school]||SCHOOL_SKINS.QC).points||'QC points';return `<div class="finance-summary"><div class="balances">${[[points,S.points],['meal points',S.meal],['looped in','$'+S.balance.toFixed(S.balance%1?2:0)]].map(([l,n])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div></div><div class="list finance-transactions">${row('You got $200 from Alyssa Pettit','navigate','receipts','May 23 2015','')}${row('You spent 50 UR at Pizza Perfect','navigate','receipts','May 1, 2015','')}${row('You got 30 Meal Points','navigate','receipts','','')}</div><div class="finance-actions">${[['make-a-purchase','Pay','pay'],['send-request-money','Send','contacts'],['reciepts','Receipts','receipts'],['notifications','Notifications','settings/alerts']].map(([i,l,r])=>B(esc(l),'navigate','',r)).join('')}</div>`;}
function merchant(){const name=param||'Pizza Place in Quincy';return `<div class="merchant-hero"><img src="${asset('32e3b2ef0c277e7083a47e674366b8ab')}" alt=""><span>Pizza place<br>in Quincy</span></div><div class="detail-heading merchant-heading"><div class="row">${B(I(S.favorites.includes(name)?'favorite':'un-favorite'),'favorite-place','icon-button heart',name)}<div><h2>${esc(name)}</h2><p>Mon-Fri 11am-7pm<br>Closed Weekends</p></div></div></div><div class="merchant-offers">${B('Earned: free drink!','expand-offer','earned-row','drink')}${merchantExpanded==='drink'?`<div class="expanded-offer"><p>Recieve a free Medium soft drink<br>With your next purchase at<br>Pizza Place in Quincy.</p><small>Coupon Valid: September 3 - November 22<br>This reward can be combined with other offers.</small></div>`:''}${B('Earned: super-mega pizza','expand-offer','earned-row','pizza')}${merchantExpanded==='pizza'?'<div class="expanded-offer">Earned: super-mega pizza</div>':''}</div><div class="list">${row('everybody 15% off','discount','','','sale')}${row('spend $15 and get a free slice next time','expand-offer','slice','','rewards')}${merchantExpanded==='slice'?'<div class="pad source-small-copy"><p>Spend $15 on your order at Pizza Place in Quincy and recieve a free cheese slice next visit!</p><small>Coupon Valid: September 3 - November 22<br>This reward can be combined with other offers.</small></div>':''}</div><img src="${A.map}" alt="Pizza Place in Quincy map" class="map">`;}
function eventDetail(){const e=events.find(e=>e.id===Number(param))||events.find(e=>e.id===1);const description='Come see the show of a lifetime! Quincy College Orchestra is performing a few of their choice pieces this Saturday with special guest, Harry Holmes, conducting.';return `<div class="event-banner">Quincy College</div><div class="detail-heading"><div class="row">${B(I(S.saved.includes(e.id)?'favorite':'un-favorite'),'favorite-event','icon-button heart',e.id)}<h2>${esc(e.title)}</h2></div><p>Starts: September ${e.date}, 2015 12:00PM</p><p>Ends: September ${e.date}, 2015 3:00PM</p></div><div class="reward-bar">${B(S.checked.includes(e.id)?'CHECKED IN':'CHECK IN','check-in',S.checked.includes(e.id)?'green':'primary',e.id)}${B(`${I('rewards')}<span>Orchestra hat</span>`,'navigate','grow icon-button','coupon/Orchestra hat')}</div>${e.id===1?`<div class="pad source-small-copy">${description}${eventExpanded?' come early and get a chance to meet Harry Homes and discuss baroque music with your fellow students.':''} ${B(eventExpanded?'less...':'more...','expand-event','inline-action')}</div>`:''}<img class="map" src="${A.map}" alt="Quincy College map"><div class="list">${row('Presidents Place 1250 Hancock Street','location','','Quincy, MA 02169','get-directions')}${row('Contact: Ben Shen (555) 567-8798','contact-info','','','call')}${row('www.Quincybandland.com','event-website','','','visit-website')}${row('Free','free','','','finances')}</div><div class="pad stack">${B('CHECK-IN WITH FACEBOOK','check-in','primary wide',e.id)}${B('CHECK-IN WITH TWITTER','check-in','primary wide',e.id)}</div>`;}
function connectPay(){return `<div class="pad"><h2 class="source-small-copy">To pay, Do one of the Following</h2><div class="card card-content"><p>${connectMode==='phone'?'1. Show your phone number to the merchant:':'1. Allow the merchant to scan the QR code below:'}</p>${connectMode==='phone'?'<div class="amount" style="font-size:28px">(555) 313-3209</div>':'<div class="source-qr"><img src="screens/pay-03.jpg" alt="Merchant payment QR code"></div>'}</div><div class="pad" style="text-align:center">OR</div>${B(connectMode==='phone'?'2. Tap to display the QR code':'2. Tap to display your phone number','connect-mode','secondary wide')}<div class="progress"><span class="active"></span><span></span></div><span class="muted source-step">step 1 of 2</span>${B('Complete Your Purchase','navigate','primary wide','purchase')}</div>`;}
function purchase(){const total=11.5+tip;return `<form id="purchase-form" class="stack pad"><div class="merchant-hero"><img src="${asset('32e3b2ef0c277e7083a47e674366b8ab')}" alt=""></div><h2 class="purchase-merchant">Pizza place in Quincy</h2><div class="row between"><span>Your Purchase:</span><span>$11.50</span></div><div class="row between"><span>Add Tip:</span><span id="tip-amount">${money(tip)}</span></div><div class="tip-grid">${[0,10,15,20].map(n=>B(n+'%','tip',Math.abs(tip-(n===15?2:11.5*n/100))<.001?'selected':'',n)).join('')}</div>${field('Other tip amount:','otherTip','number','','min="0" step="0.01" data-input="other-tip"')}<div class="total"><span>TOTAL:</span><strong id="purchase-total">${money(total)}</strong></div><button class="primary" type="submit">Complete Purchase</button><span class="muted source-step">step 2 of 2</span></form>`;}
function depositSourceScreen(){return `<div class="list">${row('From a Credit or Debit Card','choose-deposit-source','card','funds available immediately','credit-card')}${row('From a Bank Account','choose-deposit-source','bank','funds available in 2-3 business days','bank-account')}</div>`;}
function deposit(){return `<form id="deposit-form" class="pad stack"><label class="field">From:${B(depositSource?(depositSource==='bank'?'From a Bank Account':'Credit or Debit Card'):'Select an account','navigate','account-select','deposit-source')}</label>${field('Amount:','amount','number',depositDraft||'','min="0.01" step="0.01" required data-input="deposit-amount"')}<div class="total muted"><span>Your Current Balance:</span><span>${money(S.balance)}</span></div><div class="row between"><span>Amount to Add:</span><span id="add-amount">${money(depositDraft)}</span></div><div class="total"><span>NEW BALANCE:</span><strong id="new-balance">${money(S.balance+depositDraft)}</strong></div><button class="green wide" type="submit" ${depositDraft>0&&depositSource?'':'disabled'}>Add Funds</button></form>`;}
function paypalScreen(){if(paypalStage==='method')return `<div class="paypal-screen"><div class="paypal-summary"><b>looped in</b><span>My total: ${money(depositDraft)} USD</span></div><p class="paypal-by">Pay with <small>Powered by PayPal</small></p>${B('<b>Debit or credit card</b><span>Pay without exposing your card numbers.</span>','paypal-card','paypal-method')}${B('<b>PayPal CREDIT</b><span>Get 6 months to pay on all purchases of $99+*</span><small>A credit line to use with PayPal<br>Apply & get a decision in seconds<br>* Subject to credit approval. See Terms.</small>','paypal-card','paypal-method')}</div>`;
 if(paypalStage==='card')return `<form id="paypal-card-form" class="pad stack"><div class="paypal-summary"><b>looped in</b><span>My total: ${money(depositDraft)} USD</span></div><p>Pay with a card</p><label class="field"><select aria-label="Country"><option>United States</option></select></label>${field('Card number','card','text','','required inputmode="numeric" autocomplete="off"')}<span class="source-small-copy">Have a prepaid gift card?</span><div class="row">${field('Expiration:','expiration','text','','required placeholder="01 / 2015" autocomplete="off"')}${field('Security code:','security','password','','required inputmode="numeric" maxlength="4" autocomplete="off"')}</div>${field('Zip code','zip','text','','required autocomplete="off"')}${field('Email address','email','email','','required')}<button class="paypal-continue" type="submit">Continue</button></form>`;
 return `<form id="paypal-billing-form" class="pad stack"><div class="paypal-summary"><b>looped in</b><span>My total: ${money(depositDraft)} USD</span></div><p>Pay with a card</p><span>Billing info</span><div class="row">${field('First Name','first','text','','required')}${field('Last Name','last','text','','required')}</div>${field('Address line 1','address','text','','required')}<div class="row">${field('','city','text','WILMINGTON','required')}${field('','state','text','MA','required')}${field('','zip','text','01887','required')}</div><label class="row source-small-copy"><input type="checkbox" name="signup">Signup for a PayPal account (recommended)</label><p class="source-small-copy">Continue to looped in to confirm payment.</p><button class="paypal-continue" type="submit">Continue</button></form>`;}
function firstYearScreen(){return `<div class="list">${[['Thursday English Afternoons (T.E.A.)','MAY 21 | 4:00PM TO 5:30PM'],['LEARN MORE ABOUT','INTRODUCTORY SEMINARS'],['2015 Dates for Arts Intensive','AUG 30 | 12:00PM TO SEP 18 | 5:00PM'],['Thursday English Afternoons (T.E.A.)','MAY 21 | 4:00PM TO 5:30PM']].map(([t,d])=>row(t,'first-year-info',t,d,'faq')).join('')}</div><div class="finance-actions">${[['school-faculty','faculty'],['faq','FAQ'],['news-and-updates','news'],['advisor','advizor']].map(([i,t])=>B(`${I(i)}${t}`,'first-year-info','',t)).join('')}</div>`;}
function sourceDestination(title){return `<div class="source-destination">${I(title==='donations'?'donate':title==='careers'?'careers':'groups')}</div>`;}
function pinCurrent(){return `<form id="current-pin-form" class="pad stack">${field('Please enter your current PIN.','pin','password','','required pattern="[0-9]{4}" inputmode="numeric" maxlength="4" autocomplete="off"')}<button class="primary" type="submit">OK</button></form>`;}
function inviteComposer(){return `<form id="invite-form" class="pad stack"><label class="field">To:<input name="to" value="${esc(inviteContact)}" required></label><textarea name="message" aria-label="New Message" rows="12">${esc(inviteDraft)}</textarea><button type="submit" class="primary">Send</button></form>`;}
function cameraScreen(){return `<div class="camera-preview"><div class="camera-auto">Auto</div><div class="camera-frame"><img src="assets/camera-photo.svg" alt="Camera preview"></div><div class="camera-controls">${B('Cancel','back','')}${B(I('take-a-photo'),'take-picture','camera-shutter')}</div></div>`;}
function photoPreview(){return `<div class="camera-preview"><div class="camera-frame"><img src="assets/preview-photo.svg" alt="Photo preview"></div><div class="camera-controls">${B('Retake','navigate','','camera')}${B('Use Photo','use-picture','')}</div></div>`;}
function photoLibrary(){return `<div class="pad stack"><input type="file" accept="image/*" id="photo-file" aria-label="Upload Photo from Camera Roll">${B('Cancel','back','secondary')}</div>`;}
function externalBooks(){return `<div class="external-source"><img src="screens/bookstore_10.jpg" alt="Barnes & Noble source web page"><a class="external-source-link" href="https://www.barnesandnoble.com/" target="_blank" rel="noopener" aria-label="Barnes & Noble"></a></div>`;}
function bookSearchDetail(){const name=selectedCatalog||'Daren Magnus';return `<div class="toolbar">${search('Barnes & Noble Search',name+' '+bookNames[name],'book-catalog')}${B('Add Book+','add-book','secondary',name)}</div><div class="section-bar">Barnes & Noble Search</div><div class="list">${Object.entries(vampireCatalog).map(([n,t])=>row(n,'catalog-select',n,t,'bookstore')).join('')}</div>`;}
function addBooks(){const entries=Object.entries(bookNames);const q=bookQuery.toLowerCase();const useVampires=/vamp|mire|daren|lucy|jenifer|karen|von /i.test(q);const catalog=(useVampires?Object.entries(vampireCatalog):entries.filter(([n])=>!(n in vampireCatalog))).filter(([n,t])=>(n+' '+t).toLowerCase().includes(q));return `<div class="toolbar">${search('Search books',bookQuery,'book-catalog')}${B('Add Title +','add-title','secondary')}</div><div class="section-bar">${useVampires?'Barnes & Noble Search':'Bestsellers'}</div><div class="list">${catalog.map(([n,t])=>row(n,'catalog-select',n,t,'bookstore')).join('')}</div>`;}
function afterRender(){const authPage=['onboarding','school','login','role','student-id'].includes(route);if(authPage)$('.bottom')?.remove();if(['role','student-id','login'].includes(route))$('header')?.remove();if(route==='chat'){const h=$('header h1');if(h&&contactPhones[currentContact])h.innerHTML=`${esc(currentContact)}<small class="contact-header-phone">${contactPhones[currentContact]}</small>`;}if(route==='settings'&&param==='alerts')document.querySelectorAll('.list-row').forEach((r,i)=>{const sub=['Change PIN or Password','Funds Added or Withdrawn','Changes to Bank Account'][i],cat=['Security Changes','Money','Banking Information'][i];r.querySelector('.grow').insertAdjacentHTML('beforeend',`<small>${sub}</small>`);r.insertAdjacentHTML('beforeend',`<span class="muted">${S.alerts[cat]?.length?'ON':'OFF'}</span>`)});if(route==='settings'&&param==='support')$('.pad').insertAdjacentHTML('beforeend','<p class="source-small-copy">For comprehensive help and support, please visit our website at www.areyouloopedin.com.</p>');if(route==='pay-overlay'||route==='reward-overlay')showRadial(route==='pay-overlay'?'pay':'rewards');}
function showRadial(type){const entries=type==='pay'?[['make-a-purchase','pay','pay'],['reciepts','receipts','receipts'],['send-request-money','send / receive','contacts'],['deposit-funds','deposit','deposit']]:[['school-faculty','school','school-rewards'],['merchants','merchant','merchant-rewards'],['earned-reward','earned','earned'],['lou','looped in','earned']];const d=$('#dialog');d.className='radial-overlay';d.innerHTML=`<div class="radial-menu">${B(I('remove'),'close','radial-close')}${entries.map(([i,t,r])=>B(`${I(i)}<span>${t}</span>`,'radial-navigate','',r)).join('')}</div>`;d.hidden=false;$('#app').inert=true;}
// Capture only the restored flows; other controls retain the app's normal handlers.
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,v=el.dataset.value;const handled=['expand-event','expand-offer','connect-mode','choose-deposit-source','paypal-card','school-continue','tip','check-in','attach-photo','camera-choice','library-choice','take-picture','use-picture','catalog-select','first-year-info','help','radial-navigate','open-pay-overlay','open-reward-overlay'].includes(a)||(a==='setting'&&v==='pin')||(a==='profile-photo')||(a==='invite-contact')||['invite-sms','invite-email'].includes(a);if(!handled)return;e.preventDefault();e.stopImmediatePropagation();
 switch(a){case'expand-event':eventExpanded=!eventExpanded;render();break;case'expand-offer':merchantExpanded=merchantExpanded===v?'':v;render();break;case'connect-mode':connectMode=connectMode==='phone'?'qr':'phone';render();break;
 case'school-continue':if(!['QC','BU','GC'].includes(schoolChoice)){return;}S.school=schoolChoice;save();nav('role');break;
 case'choose-deposit-source':depositSource=v;if(v==='bank'&&!S.bank){modal('Add a Bank Account','<p>To add funds from a bank account, you must first add and verify an account. Verification can take 2-3 days to complete. To add funds instantly, add with a credit or debit card.</p>',[['Cancel','close'],['Add Account','navigate','settings/add-bank']]);}else nav('deposit');break;
 case'paypal-card':paypalStage='card';render();break;case'tip':tip=Number(v)===15?2:11.5*Number(v)/100;render();break;
 case'check-in':{const id=Number(v);if(id!==1){toast("Uh-ho,time travel alert!\nthe event hasn't started yet\nor you are not there yet.\ntry again when you arrive.");return;}if(!S.checked.includes(id)){S.checked.push(id);if(!S.earned.includes('Orchestra hat'))S.earned.push('Orchestra hat');save();render();toast('You checked in at Concert in Central Hall!')}break;}
 case'attach-photo':modal('', '',[['Take Photo','camera-choice'],['Upload Photo from Camera Roll','library-choice'],['Cancel','close']]);break;case'camera-choice':close();nav('camera');break;case'library-choice':close();nav('photo-library');break;case'take-picture':nav('photo-preview');break;case'use-picture':{pendingPhoto='source-cup';nav('chat',currentContact);break;}
 case'profile-photo':modal('', '',[['Take Photo','profile-upload'],['Upload Photo from Camera Roll','profile-upload'],['Log Out from the App','logout'],['Cancel','close']]);break;
 case'setting':nav('pin-current');break;case'invite-contact':inviteContact=v;modal(v,'',[['Invite via SMS','invite-sms'],['Invite via Email','invite-email'],['Cancel','close']]);break;
 case'invite-sms':case'invite-email':inviteDraft='A friend has invited you to check out looped in, the mobile payment app with exclusive member deals. Check it out in the App Store http://tinyurl.com/o88s387 or The Google Play Store http://tinyurl.com/mdercjb';close();nav('invite-compose');break;
 case'catalog-select':selectedCatalog=v;nav('book-search');break;
 case'first-year-info':toast(v);break;case'help':nav('settings','support');break;
 case'radial-navigate':close();navigateRaw(v);break;case'open-pay-overlay':showRadial('pay');break;case'open-reward-overlay':showRadial('rewards');break;
 }
},true);
