let fashionTab='college fashion';
function fashion(){const cats=['Hi Mom & Dad','Back To School','Gifts for a Graduate','Alumni Nostalgia','Quincy’s Super Fan Collection','Quincy for Her','Quincy for Him','Quincy Tech'];return tabs(['featured','college fashion'],fashionTab,'fashion-tab')+`<div class="fashion-categories">${cats.map((t,i)=>B(`<strong>${t}</strong>`,'navigate',`reward-tile ${i===4||i===7?'span-two':''}`,'product')).join('')}</div>`;}
