const pizzaOnlyMerchant=merchant;
merchant=function(){if(!param||param==='Pizza Place in Quincy')return pizzaOnlyMerchant();const entry=merchants.find(([n])=>n===param);if(!entry)return '';return `<img class="merchant-image" src="${entry[1]}" alt="${esc(param)}"><div class="detail-heading"><div class="row">${B(I(S.favorites.includes(param)?'favorite':'un-favorite'),'favorite-place','icon-button heart',param)}<h2>${esc(param)}</h2></div></div>`;};
