document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='bank-form')return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));S.bank={name:d.name,holder:d.holder,account:d.account.slice(-4).padStart(d.account.length,'•')};save();nav('settings','bank');modal('Add a Bank Account','<p>To add funds from a bank account, you must first add and verify an account. Verfications can take 2-3 days to complete. To add funds instantly, add with a credit or debit card.</p>',[['Cancel','close'],['Add Account','close']]);},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['add-cart','confirm-cart','show-cart','remove-cart'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='add-cart'||b.dataset.action==='confirm-cart'){S.cart=(S.cart||0)+1;save();close();render();}else if(b.dataset.action==='remove-cart'){S.cart=0;save();close();render();}else{modal('Quincy Scarf with Logo',`<p>One size</p><p>$25.00${S.cart>1?' × '+S.cart:''}</p>`,[['Cancel','close'],['Remove','remove-cart']]);}},true);
