let distanceChoice='.5';
function merchantGrid(isRewards=false){const selected=isRewards?rewardTab:placeTab;const earnedMerchants=['Pizza Place in Quincy','Lacrosse USA','Donfredi’s','Cosmopolitan Sushi',"Hot Dog n’ more"];const visible=merchants.filter(([n])=>selected==='favorites'?S.favorites.includes(n):isRewards&&selected==='my rewards'?earnedMerchants.includes(n):true);return tabs(isRewards?['all merchants','favorites','my rewards']:['all places','favorites','map'],selected,isRewards?'reward-tab':'place-tab')+`<div class="toolbar merchant-toolbar">${search('Search places','','place-search')}<div class="distance-picker">${['.5','1','10'].map(d=>B(d+' mi','distance',d===distanceChoice?'selected':'',d)).join('')}</div></div><div id="merchant-results">${selected==='map'?`<button class="wide icon-button" data-action="navigate" data-value="merchant"><img src="${A.map}" alt="Places map" style="width:100%"></button>`:`<div class="merchant-grid">${visible.map(([n,img])=>`<div class="merchant-card"><button class="merchant-picture" data-action="merchant" data-value="${esc(n)}"><img src="${img}" alt="${esc(n)}"></button><div class="caption">${B(merchantHeart(S.favorites.includes(n)),'favorite-place','icon-button heart',n)}${earnedMerchants.includes(n)?`<span class="earned-reward-badge" role="img" aria-label="Reward earned">${merchantTrophy()}</span>`:''}</div></div>`).join('')}</div>`}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['reward-tab','distance'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='reward-tab')rewardTab=b.dataset.value;else distanceChoice=b.dataset.value;render();},true);
