function filterScreen(){const arts=['Auditions','Concerts','Dance','Film','Galleries and exhibits','Master classes'];return `<div class="filter-underlay" inert>${faithfulEvents()}</div><button class="filter-dismiss" data-action="apply-filter" aria-label="Close Event Filters"></button><aside class="filter-drawer"><div class="filter-title"><h2>Event Filters</h2>${B('Clear Filter','clear-filter','secondary')}</div><div class="filter-options">${['Featured events','Arts','Careers','Charity and voluntering','Workshops','Clubs','Alumin','First year'].map(t=>t==='Arts'?`<div class="check-row"><button class="inline-action" data-action="expand-art-filter">Arts</button><input type="checkbox" aria-label="Arts" data-filter="Arts" ${filterDraft.has('Arts')?'checked':''}></div>${filterExpanded||arts.some(a=>filterDraft.has(a))?`<div class="filter-group">${arts.map(a=>`<label class="check-row ${filterDraft.has(a)?'filter-selected':''}">${a}<input type="checkbox" data-filter="${a}" ${filterDraft.has(a)?'checked':''}></label>`).join('')}</div>`:''}`:`<label class="check-row">${t}<input type="checkbox" data-filter="${t}" ${filterDraft.has(t)?'checked':''}></label>`).join('')}</div></aside>`;}
