document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='expand-art-filter'){e.preventDefault();e.stopImmediatePropagation();filterExpanded=!filterExpanded;render()}else if(b.dataset.action==='back'&&route==='onboarding'&&formStage>0){e.preventDefault();e.stopImmediatePropagation();formStage--;render()}},true);
const sourceAlert=modal;
modal=function(title,body,buttons=[['OK','close']]){sourceAlert(title,body,buttons);const d=$('#dialog'),form=d.querySelector('.dialog-body form'),submit=form?.querySelector('button[type=submit]');if(form&&submit&&buttons.length===1&&buttons[0][0]==='Cancel'){const button=document.createElement('button');button.type='button';button.dataset.action='submit-modal-form';button.dataset.value=form.id;button.textContent=submit.textContent;submit.remove();d.querySelector('.dialog-actions').append(button);}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="submit-modal-form"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();document.getElementById(b.dataset.value)?.requestSubmit();},true);
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='add-list-form')return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));bookList=d.course;if(!S.booklists.includes(bookList))S.booklists.splice(Math.max(1,S.booklists.length-1),0,bookList);S.sections||={};S.sections[bookList]=d.section;save();nav('books');},true);


const beforeNativeAuth=auth;
auth=function(){
 if(route==='school')return `<section class="live-auth school-picker-page"><div class="live-auth-brand">${collegeLogo(schoolChoice)}<img class="wordmark" src="assets/wordmark.png" alt="looped in"></div><div class="live-school-picker"><p>${registration?'SELECT YOUR SCHOOL':'CHANGE YOUR SCHOOL'}</p><div class="school-choices">${['H','BU','QC','GC','SH'].map(t=>B(t,'school-choice',schoolChoice===t?'selected':'',t)).join('')}</div></div>${B('CONTINUE','school-continue','live-auth-continue')}</section>`;
 if(['role','student-id','login'].includes(route)||route==='onboarding'&&formStage>=4){
 const isID=route==='student-id',isLogin=route==='login';
 return `<form id="${isLogin?'login-form':isID?'student-id-form':'choose-role-form'}" class="live-auth"><div class="live-auth-brand">${collegeLogo(schoolChoice)}<img class="wordmark" src="assets/wordmark.png" alt="looped in"></div><div class="live-auth-fields">${isLogin?`<input name="student" type="tel" aria-label="Phone number" value="${esc(authData.phone||'555 332 1621')}" required><input name="password" type="password" aria-label="Password" autocomplete="off" required><label class="live-remember"><span>REMEMBER ME</span><input class="switch" type="checkbox" name="remember"></label>${B('FORGOT PASSWORD','forgot','live-forgot')}`:isID?`<input name="student" type="text" aria-label="ENTER YOUR STUDENT ID" placeholder="ENTER YOUR STUDENT ID" required>`:`<select name="role" aria-label="I AM ..." required><option value="">I AM ...</option>${['Student','First Year Student','Alumni','Parent/Gardian'].map(t=>`<option ${authData.role===t?'selected':''}>${t}</option>`).join('')}</select>`}</div><button class="live-auth-continue" type="submit">${isLogin?'LOGIN':isID?'FINISH':'CONTINUE'}</button></form>`;
 }
 return beforeNativeAuth();
};


const beforeCouponActions=coupon;
