function merchantTrophy(){return `<svg class="merchant-overlay-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 3h10v7a5 5 0 0 1-10 0V3Z"/><path d="M7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4M12 15v4M8 21h8M9 19h6"/><path d="m12 6 1 2 2.2.3-1.6 1.6.4 2.1-2-1-2 1 .4-2.1L8.8 8.3 11 8 12 6Z" stroke-width="1.25"/></svg>`;}
